{

"kind": "propose",
"summary": "The 'api' container's CPU limit is too low, causing throttling and readiness probe failures. Increasing the CPU limit to 450m will resolve this.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "CPU usage is near the limit (0.296/0.3) with 55% throttling, causing readiness probe timeouts.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "Container logs are empty, which could indicate memory issues but doesn't negate CPU throttling evidence.",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "The CPU limit will be increased to 450m, allowing the container to use more CPU and avoid throttling, improving readiness probe success.",
  "rationale": "The container is throttled at 300m (0.296/0.3 usage) with 55% throttling, causing readiness probe timeouts. Raising the limit to 450m (1.5x current) should clear throttling. Empty logs don't contradict CPU throttling evidence, as memory issues aren't part of this fix.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
